// Demo: Data Importer definition of done - practitioner discipline
(function(){'use strict';
var DATA={"label": "Data Importer definition of done - practitioner discipline", "docs": [{"id": "AIB-DIP-000001", "text": "Data Importer - public implementations survey. Loads data from supported files, databases, and external services."}, {"id": "AIB-DIP-000002", "text": "Logstash - related Data Importer technology. Elastic's log ingestion pipeline."}, {"id": "AIB-DIP-000003", "text": "Fluentd - related Data Importer technology. Unified logging layer in CNCF."}, {"id": "AIB-DIP-000004", "text": "Airbyte - related Data Importer technology. Open-source data integration connectors."}, {"id": "AIB-DIP-000005", "text": "RSS feeds - related Data Importer technology. Syndication formats for update ingestion."}, {"id": "AIB-DIP-000006", "text": "Apache Kafka - related Data Importer technology. Distributed event-streaming platform; the standard backbone for real-time ingestion."}], "query": "definition"};

var idx={};
DATA.docs.forEach(function(d){
  d.text.toLowerCase().split(/[^a-z0-9]+/).forEach(function(t){
    if(!t)return;(idx[t]=idx[t]||{})[d.id]=(idx[t][d.id]||0)+1;});});
var q=DATA.query.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean),scores={};
q.forEach(function(t){var post=idx[t]||{};
  Object.keys(post).forEach(function(id){scores[id]=(scores[id]||0)+post[id];});});
var ranked=Object.keys(scores).sort(function(a,b){return scores[b]-scores[a];});
console.log('Query "'+DATA.query+'" ('+DATA.label+'):');
if(!ranked.length)console.log('  no matches');
ranked.forEach(function(id,i){var d=DATA.docs.filter(function(x){return x.id===id;})[0];
  console.log('  '+(i+1)+'. '+d.id+' score='+scores[id]+' :: '+d.text.slice(0,60));});
})();

